$ErrorActionPreference='Stop'; $output = & dotnet run --project "$PSScriptRoot/starter/TicketLab.csproj" 2>&1; $code=$LASTEXITCODE; $output | ForEach-Object { Write-Output $_ }; if ($code -eq 0 -and (($output -join "`n") -match 'Allocations=1') -and (($output -join "`n") -match 'Returned=(\d+),\1')) { Write-Host 'PASS: single allocation and matching callers'; exit 0 }; Write-Error "Verification failed (exit=$code)"; exit 1
